#!/bin/bash

# This is sshpass a cool utility:
# since ssh block the terminal to ask you a password (and it's uncomfortable to write it every time)
# it will insert it for us (YOU NEED TO HAVE IT INSTALLED)
# I WROTE IT IN THE DOCUMENTATION, IT'S THE THIRD LINE PLEASE READ IT
# we need -t to open a remote terminal (needed for docker run -it)
# the use of EOF is needed because it will send the next commands in the terminal generated by the SSH
sshpass -p "ciaociao" ssh -X -t isaac@192.168.8.112 << 'EOF'

# Now you're in the jetson
# We need to run the docker container that contains everything
# If you changed something please rebuilt it! >:(

# Check if "robot" session already exists
if ! tmux has-session -t robot 2>/dev/null; then
    echo "No active session found. Creating a new tmux 'robot' and starting the container..."
    
    # Create a background tmux session detached (-d) called "robot"
    tmux new-session -d -s robot
    
    # Send the command to the new session
    tmux send-keys -t robot 'docker run -it --rm --privileged \
      --volume /lib/modules:/lib/modules:ro \
      --volume /usr/src:/usr/src:ro \
      --runtime nvidia \
      --gpus all \
      --network host \
      -e DISPLAY=$DISPLAY \
      -v /tmp/.X11-unix:/tmp/.X11-unix \
      --volume /dev/input:/dev/input \
      -v /home/isaac/.Xauthority:/root/.Xauthority:ro \
      reseq-orin \
      /bin/bash -c "source /ros_entrypoint.sh && ros2 launch reseq_ros2 reseq_launch.py config_file:=reseq_mk2_can.yaml sensors:=false cv:=false"' C-m
else
    echo "'robot' session found. Reconnecting to ROS..."
fi

# Attach terminal to the current session of tmux
tmux attach-session -t robot

# This line is needed since the sshpass above will send every commands above this EOF 
EOF
